#!/usr/bin/env node

/**
 * BULLETPROOF Database Setup for Render
 *
 * Why this exists:
 * - Prisma's `db push` uses prepared statements which FAIL on PgBouncer transaction mode
 * - Prisma's `migrate deploy` also fails for the same reason
 * - This script uses raw SQL via the `pg` client, which works everywhere
 *
 * What it does:
 * 1. Reads the full-schema.sql generated by `prisma migrate diff`
 * 2. Strips SQL comments, splits into individual statements
 * 3. Executes each SQL statement individually (with IF NOT EXISTS where possible)
 * 4. Creates/updates the super admin user
 * 5. Logs EVERYTHING - no silent failures
 */

const { Client } = require("pg");
const fs = require("fs");
const path = require("path");
const bcrypt = require("bcryptjs");

// ============================
// LOGGING
// ============================
const LOG_PREFIX = "[BULLETPROOF-SETUP]";
const log = (msg) =>
	console.log(`${new Date().toISOString()} ${LOG_PREFIX} ${msg}`);
const logError = (msg, err) => {
	console.error(`${new Date().toISOString()} ${LOG_PREFIX} ❌ ${msg}`);
	if (err)
		console.error(
			`${new Date().toISOString()} ${LOG_PREFIX} ERROR:`,
			err.message || err,
		);
	if (err?.stack)
		console.error(
			`${new Date().toISOString()} ${LOG_PREFIX} STACK:`,
			err.stack,
		);
};
const logSuccess = (msg) =>
	console.log(`${new Date().toISOString()} ${LOG_PREFIX} ✅ ${msg}`);
const logWarn = (msg) =>
	console.warn(`${new Date().toISOString()} ${LOG_PREFIX} ⚠️ ${msg}`);

/**
 * Parse SQL file into executable statements.
 * - Strips all comment lines (lines starting with --)
 * - Strips BOM and normalizes line endings
 * - Splits on semicolons
 * - Filters out empty statements
 */
function parseSQLStatements(rawSQL) {
	// Strip BOM if present
	let sql = rawSQL.replace(/^\uFEFF/, "");

	// Normalize line endings (Windows \r\n -> \n)
	sql = sql.replace(/\r\n/g, "\n").replace(/\r/g, "\n");

	// Remove all comment lines (lines that start with --)
	sql = sql
		.split("\n")
		.filter((line) => !line.trim().startsWith("--"))
		.join("\n");

	// Split by semicolons into individual statements
	const statements = sql
		.split(";")
		.map((s) => s.trim())
		.filter((s) => s.length > 0);

	return statements;
}

async function bulletproofSetup() {
	log("🚀 Starting BULLETPROOF database setup...");
	log(`📋 Environment: NODE_ENV=${process.env.NODE_ENV}`);
	log(
		`📋 ADMIN_EMAIL configured: ${process.env.ADMIN_EMAIL ? "YES" : "NO (using fallback)"}`,
	);
	log(
		`📋 ADMIN_PASSWORD configured: ${process.env.ADMIN_PASSWORD ? "YES (" + process.env.ADMIN_PASSWORD.length + " chars)" : "NO (using fallback)"}`,
	);
	log(
		`📋 BCRYPT_SALT_ROUNDS: ${process.env.BCRYPT_SALT_ROUNDS || "12 (default)"}`,
	);

	const databaseUrl = process.env.DATABASE_URL;
	if (!databaseUrl) {
		logError("DATABASE_URL is not set! Cannot proceed.");
		process.exit(1);
	}

	// Mask the URL for logging
	const maskedUrl = databaseUrl.replace(/:([^@]+)@/, ":****@");
	log(`🔗 Connecting to: ${maskedUrl}`);

	const client = new Client({
		connectionString: databaseUrl,
		ssl: { rejectUnauthorized: false },
		connectionTimeoutMillis: 30000,
		statement_timeout: 120000,
	});

	try {
		await client.connect();
		logSuccess("Database connection established");

		// =========================================================
		// EMERGENCY PATCH: Fix nullable unique constraints & data
		// Ensures "" is replaced by NULL and alters existing table constraints
		// =========================================================
		log("🩹 [EMERGENCY-PATCH] Running structural data and schema repairs...");
		try {
			// 1. Safe Data cleanup
			log(
				"  🧹 Converting empty string phones and emails to NULL in existing records...",
			);
			await client
				.query(`UPDATE "UserProfile" SET phone = NULL WHERE phone = ''`)
				.catch(() => {});
			await client
				.query(`UPDATE "UserProfile" SET email = NULL WHERE email = ''`)
				.catch(() => {});
			await client
				.query(`UPDATE "User" SET phone = NULL WHERE phone = ''`)
				.catch(() => {});
			await client
				.query(`UPDATE "User" SET email = NULL WHERE email = ''`)
				.catch(() => {});

			// 2. Alter Column constraints to allow NULL values for unique indexes
			log(
				"  🏗️ Dropping NOT NULL constraints from phone and email columns if they exist...",
			);
			await client
				.query(`ALTER TABLE "UserProfile" ALTER COLUMN phone DROP NOT NULL`)
				.catch(() => {});
			await client
				.query(`ALTER TABLE "UserProfile" ALTER COLUMN email DROP NOT NULL`)
				.catch(() => {});
			await client
				.query(`ALTER TABLE "User" ALTER COLUMN phone DROP NOT NULL`)
				.catch(() => {});
			await client
				.query(`ALTER TABLE "User" ALTER COLUMN email DROP NOT NULL`)
				.catch(() => {});

			// 3. Apply missing schema updates (ownerPrice, contact replies)
			log("  🏗️ Applying missing schema columns...");
			await client.query(`ALTER TABLE "Product" ADD COLUMN IF NOT EXISTS "ownerPrice" DOUBLE PRECISION DEFAULT 0`).catch(() => {});
			
			await client.query(`ALTER TABLE "ContactSubmission" ADD COLUMN IF NOT EXISTS "isReplied" BOOLEAN DEFAULT false`).catch(() => {});
			await client.query(`ALTER TABLE "ContactSubmission" ADD COLUMN IF NOT EXISTS "replyText" TEXT`).catch(() => {});
			await client.query(`ALTER TABLE "ContactSubmission" ADD COLUMN IF NOT EXISTS "repliedAt" TIMESTAMP(3)`).catch(() => {});
			await client.query(`ALTER TABLE "ContactSubmission" ADD COLUMN IF NOT EXISTS "repliedBy" TEXT`).catch(() => {});

			logSuccess(
				"[EMERGENCY-PATCH] Structural database repairs executed successfully!",
			);
		} catch (patchErr) {
			logWarn(
				`[EMERGENCY-PATCH] Repair task completed with notice: ${patchErr.message}`,
			);
		}

		// ============================================
		// STEP 1: Count existing tables
		// ============================================
		const beforeCount = await client.query(`
            SELECT count(*)::int as cnt FROM information_schema.tables 
            WHERE table_schema = 'public' AND table_type = 'BASE TABLE'
        `);
		log(`📊 Tables before setup: ${beforeCount.rows[0].cnt}`);

		// ============================================
		// STEP 2: Read and execute full schema SQL
		// ============================================
		const sqlFilePath = path.join(__dirname, "full-schema.sql");
		if (!fs.existsSync(sqlFilePath)) {
			logError(`SQL file not found at: ${sqlFilePath}`);
			process.exit(1);
		}

		log("📄 Reading full-schema.sql...");
		const rawSQL = fs.readFileSync(sqlFilePath, "utf-8");
		log(`📄 File size: ${rawSQL.length} chars`);

		const statements = parseSQLStatements(rawSQL);
		log(`📦 Found ${statements.length} SQL statements to execute`);

		// Log first 3 statements for debugging
		for (let i = 0; i < Math.min(3, statements.length); i++) {
			log(
				`  📝 Statement ${i + 1} preview: ${statements[i].substring(0, 80)}...`,
			);
		}

		let executed = 0;
		let skipped = 0;
		let failed = 0;

		for (let i = 0; i < statements.length; i++) {
			let stmt = statements[i];

			if (!stmt) {
				skipped++;
				continue;
			}

			try {
				// Make CREATE TABLE idempotent
				if (
					/CREATE\s+TABLE\s+/i.test(stmt) &&
					!stmt.includes("IF NOT EXISTS")
				) {
					stmt = stmt.replace(
						/CREATE\s+TABLE\s+/i,
						"CREATE TABLE IF NOT EXISTS ",
					);
				}

				// Make CREATE SCHEMA idempotent
				if (
					/CREATE\s+SCHEMA\s+/i.test(stmt) &&
					!stmt.includes("IF NOT EXISTS")
				) {
					stmt = stmt.replace(
						/CREATE\s+SCHEMA\s+/i,
						"CREATE SCHEMA IF NOT EXISTS ",
					);
				}

				// Make CREATE INDEX idempotent
				if (
					/CREATE\s+UNIQUE\s+INDEX\s+/i.test(stmt) &&
					!stmt.includes("IF NOT EXISTS")
				) {
					stmt = stmt.replace(
						/CREATE\s+UNIQUE\s+INDEX\s+/i,
						"CREATE UNIQUE INDEX IF NOT EXISTS ",
					);
				} else if (
					/CREATE\s+INDEX\s+/i.test(stmt) &&
					!stmt.includes("IF NOT EXISTS")
				) {
					stmt = stmt.replace(
						/CREATE\s+INDEX\s+/i,
						"CREATE INDEX IF NOT EXISTS ",
					);
				}

				// Handle CREATE TYPE (enums) - check if already exists
				if (/CREATE\s+TYPE\s+/i.test(stmt)) {
					const typeMatch = stmt.match(/CREATE\s+TYPE\s+"?(\w+)"?\s+AS/i);
					if (typeMatch) {
						const typeName = typeMatch[1];
						const exists = await client.query(
							`SELECT 1 FROM pg_type WHERE typname = $1`,
							[typeName],
						);
						if (exists.rows.length > 0) {
							skipped++;
							continue;
						}
					}
				}

				await client.query(stmt);
				executed++;
			} catch (err) {
				if (
					err.message.includes("already exists") ||
					err.message.includes("duplicate key") ||
					err.message.includes("already defined") ||
					err.message.includes("multiple primary keys")
				) {
					skipped++;
				} else {
					failed++;
					logWarn(`Statement ${i + 1} failed: ${err.message}`);
					logWarn(`Statement was: ${stmt.substring(0, 150)}...`);
				}
			}
		}

		log(
			`📊 SQL Execution Summary: ${executed} executed, ${skipped} skipped (already exist), ${failed} failed`,
		);

		// ============================================
		// STEP 3: Verify tables after setup
		// ============================================
		const afterCount = await client.query(`
            SELECT count(*)::int as cnt FROM information_schema.tables 
            WHERE table_schema = 'public' AND table_type = 'BASE TABLE'
        `);
		log(`📊 Tables after setup: ${afterCount.rows[0].cnt}`);

		const criticalTables = [
			"Admin",
			"User",
			"Product",
			"Category",
			"Order",
			"CartItem",
		];
		let allCriticalExist = true;
		for (const table of criticalTables) {
			const exists = await client.query(
				`
                SELECT EXISTS (
                    SELECT FROM information_schema.tables 
                    WHERE table_schema = 'public' AND table_name = $1
                )
            `,
				[table],
			);
			const ok = exists.rows[0].exists;
			const status = ok ? "✅" : "❌";
			log(`  ${status} Table "${table}": ${ok ? "EXISTS" : "MISSING!"}`);
			if (!ok) allCriticalExist = false;
		}

		if (!allCriticalExist) {
			logError("Some critical tables are STILL missing after schema setup!");
			logError(
				"This likely means the SQL file has issues or the database connection is read-only.",
			);
			await client.end();
			process.exit(1);
		}

		// ============================================
		// STEP 4: Create/Update Super Admin
		// ============================================
		log("👤 Setting up Super Admin...");

		const adminEmail =
			process.env.ADMIN_EMAIL || "mahakal.mahakali014@gmail.com";
		const adminPassword = process.env.ADMIN_PASSWORD || "Kali@0786";
		const adminName = process.env.ADMIN_NAME || "Super Admin";
		const saltRounds = parseInt(process.env.BCRYPT_SALT_ROUNDS || "12");

		log(`  📧 Admin Email: ${adminEmail}`);
		log(`  🔐 Password length: ${adminPassword.length} chars`);
		log(`  🧂 Salt rounds: ${saltRounds}`);

		// Hash password
		log("  🔒 Hashing password...");
		const passwordHash = await bcrypt.hash(adminPassword, saltRounds);
		log(`  🔒 Hash generated: ${passwordHash.substring(0, 20)}...`);

		// Check if admin exists
		const existingAdmin = await client.query(
			'SELECT id, email, "passwordHash" FROM "Admin" WHERE email = $1',
			[adminEmail],
		);

		if (existingAdmin.rows.length > 0) {
			log("  📝 Admin exists, updating password hash...");
			await client.query(
				'UPDATE "Admin" SET "passwordHash" = $1, "updatedAt" = NOW(), name = $2 WHERE email = $3',
				[passwordHash, adminName, adminEmail],
			);
			logSuccess(`Super Admin password updated for: ${adminEmail}`);
		} else {
			log("  📝 Creating new admin...");
			await client.query(
				`
                INSERT INTO "Admin" (id, email, name, "passwordHash", role, "isActive", "createdAt", "updatedAt")
                VALUES (gen_random_uuid()::text, $1, $2, $3, 'SUPER_ADMIN', true, NOW(), NOW())
            `,
				[adminEmail, adminName, passwordHash],
			);
			logSuccess(`Super Admin created: ${adminEmail}`);
		}

		// ============================================
		// STEP 5: Final verification
		// ============================================
		log("🔍 Final verification...");

		const finalAdmin = await client.query(
			'SELECT id, email, role, "isActive", "passwordHash" FROM "Admin" WHERE email = $1',
			[adminEmail],
		);

		if (finalAdmin.rows.length === 0) {
			logError("CRITICAL: Admin user not found after setup!");
			await client.end();
			process.exit(1);
		}

		const admin = finalAdmin.rows[0];
		const finalMatch = await bcrypt.compare(adminPassword, admin.passwordHash);
		logSuccess(
			`Final state: Admin ${admin.email} (${admin.role}) active=${admin.isActive} password_match=${finalMatch}`,
		);

		if (!finalMatch) {
			logError(
				"CRITICAL: Password does not match after setup! Login WILL fail.",
			);
			await client.end();
			process.exit(1);
		}

		await client.end();
		logSuccess("🎉 BULLETPROOF setup completed successfully!");
		process.exit(0);
	} catch (error) {
		logError("Setup failed catastrophically", error);
		try {
			await client.end();
		} catch (e) {
			/* ignore */
		}
		process.exit(1);
	}
}

bulletproofSetup();
